# bit helpers
ALL_LABELS=(1<<(m+1))-1

def search_case(init_assign, max_nodes=1000000, verbose=False):
    labels=[-1]*N
    used_labels=0
    edge_diff=[0]*len(edges)  # assigned diff or 0
    diff_edge=[-1]*(m+1)
    assigned_edges=0
    nodes=0
    # assign initial labels and diff 36 if edge pair
    for v,l in init_assign.get('labels',[]):
        labels[v]=l; used_labels |= 1<<l
    for ei,d in init_assign.get('edges',[]):
        edge_diff[ei]=d; diff_edge[d]=ei; assigned_edges |= 1<<ei
    # validate init
    def validate():
        # label uniqueness assumed; fully assigned edge diffs distinct and consistent with assignments
        seen={} # d->ei for fully assigned edges
        for ei,(u,v) in enumerate(edges):
            if labels[u]!=-1 and labels[v]!=-1:
                d=abs(labels[u]-labels[v])
                if d==0: return False
                ae=diff_edge[d]
                if ae!=-1 and ae!=ei:
                    return False
                if d in seen and seen[d]!=ei:
                    return False
                seen[d]=ei
                if edge_diff[ei]!=0 and edge_diff[ei]!=d:
                    return False
            # if edge assigned, endpoints should be assigned? In our placements always assign endpoints if needed.
            if edge_diff[ei]!=0:
                if labels[u]==-1 or labels[v]==-1: return False
                if abs(labels[u]-labels[v])!=edge_diff[ei]: return False
        return True
    if not validate(): return None, nodes

    # candidate gen returns list of (ei, assignlist[(v,l),...])
    def candidates_for_diff(d):
        if diff_edge[d]!=-1: return None
        c=[]
        for ei,(u,v) in enumerate(edges):
            if edge_diff[ei]!=0: continue
            lu,lv=labels[u],labels[v]
            if lu!=-1 and lv!=-1:
                if abs(lu-lv)==d:
                    c.append((ei,()))
            elif lu!=-1 or lv!=-1:
                if lu==-1:
                    # v assigned lv; u = lv +/- d
                    for val in (lv-d, lv+d):
                        if 0<=val<=m and not (used_labels>>val)&1:
                            c.append((ei,((u,val),)))
                else:
                    for val in (lu-d, lu+d):
                        if 0<=val<=m and not (used_labels>>val)&1:
                            c.append((ei,((v,val),)))
            else:
                # both unassigned: any pair a,a+d, two orientations
                avail_pairs=[]
                mask=used_labels
                for a in range(0,m-d+1):
                    b=a+d
                    if ((mask>>a)&1)==0 and ((mask>>b)&1)==0:
                        c.append((ei,((u,a),(v,b))))
                        c.append((ei,((u,b),(v,a))))
        return c

    def global_prune():
        # Validate fully assigned duplicate diffs and used conflict. Also count forced maybe.
        # For every fully assigned unassigned edge, diff must be unused and unique among such.
        seen=[] # not set? use dict list
        seen_by={}
        for ei,(u,v) in enumerate(edges):
            lu,lv=labels[u],labels[v]
            if lu!=-1 and lv!=-1:
                d=abs(lu-lv)
                if d==0: return False
                ae=diff_edge[d]
                if ae!=-1 and ae!=ei: return False
                if d in seen_by and seen_by[d]!=ei: return False
                seen_by[d]=ei
                if edge_diff[ei]!=0 and edge_diff[ei]!=d: return False
        # each unused diff must have at least one candidate? maybe do for constrained d only via selection
        return True

    def dfs(depth=0):
        nonlocal nodes, used_labels, assigned_edges
        nodes+=1
        if nodes%100000==0 and verbose:
            print('nodes',nodes,'depth',depth,'assigned edges',assigned_edges.bit_count(),'used labels',used_labels.bit_count(),'labels',labels, flush=True)
        if nodes>max_nodes:
            raise TimeoutError
        if assigned_edges.bit_count()==len(edges):
            if len(set(labels))==N and min(labels)>=0 and validate():
                return labels.copy()
            return None
        if not global_prune():
            return None
        # forced assignment for any unassigned edge fully labeled? Instead maybe assign its diff immediately? We can propagate deterministic if diff unused.
        # Let's not mutate here? Could recursively place all forced edge labels with fixed diff to reduce.
        forced=[]
        for ei,(u,v) in enumerate(edges):
            if edge_diff[ei]==0 and labels[u]!=-1 and labels[v]!=-1:
                d=abs(labels[u]-labels[v])
                if diff_edge[d]!=-1: return None
                forced.append((d,ei))
        if forced:
            # If multiple, assign all (diffs unique checked)
            changed=[]
            for d,ei in forced:
                if edge_diff[ei]!=0: continue
                if diff_edge[d]!=-1: # may have assigned by earlier forced? duplicate
                    # if same edge impossible since edge was unassigned
                    for dd,ee in reversed(changed):
                        edge_diff[ee]=0; diff_edge[dd]=-1; assigned_edges &= ~(1<<ee)
                    return None
                edge_diff[ei]=d; diff_edge[d]=ei; assigned_edges |= 1<<ei; changed.append((d,ei))
            res=dfs(depth+len(changed))
            for d,ei in reversed(changed):
                edge_diff[ei]=0; diff_edge[d]=-1; assigned_edges &= ~(1<<ei)
            return res
        # select unused diff with min candidates; maybe only diffs possible. prioritize high? compute all until min low.
        best_d=None; best_c=None; best_len=10**9
        # first check assigned fully none.
        # Use high-to-low and break if candidate count 1; skip very small? no need.
        for d in range(m,0,-1):
            if diff_edge[d]!=-1: continue
            c=candidates_for_diff(d)
            clen=len(c)
            if clen==0:
                return None
            # scoring: min candidates, tie bigger d
            if clen<best_len:
                best_len=clen; best_c=c; best_d=d
                if clen==1: break
        d=best_d; cands=best_c
        # order cands: prefer assignments involving existing labels, high labels? and edges near assigned vertices.
        def score(c):
            ei, assigns=c
            # fewer new vertices first
            s=len(assigns)*100
            # prefer edge with many adjacent assigned? maybe
            u,v=edges[ei]
            s-=sum(labels[w]!=-1 for _,w in adj_edges[u]+adj_edges[v])
            return s
        cands.sort(key=score)
        for ei,assigns in cands:
            # apply: check labels still consistent and unique
            new=[]; old_used=used_labels
            ok=True
            # assign labels
            for v,l in assigns:
                if labels[v]!=-1:
                    if labels[v]!=l: ok=False; break
                elif (used_labels>>l)&1:
                    ok=False; break
                else:
                    labels[v]=l; used_labels |= 1<<l; new.append(v)
            if ok:
                # set edge diff
                edge_diff[ei]=d; diff_edge[d]=ei; assigned_edges |= 1<<ei
                # optional local prune: new vertex edges duplicate
                if global_prune():
                    res=dfs(depth+1)
                    if res is not None: return res
                edge_diff[ei]=0; diff_edge[d]=-1; assigned_edges &= ~(1<<ei)
            # undo labels
            for v in reversed(new): labels[v]=-1
            used_labels=old_used
        return None
    try:
        res=dfs()
        return res,nodes
    except TimeoutError:
        return 'timeout', nodes

